// Appele depuis la sortie 10 (heroPayload) de fn_normalize
const d = msg.payload;
const deviceId = d.device || 'unknown';

// Stocker la derniere lecture
let devices = flow.get('api_devices') || {};
devices[deviceId] = {
    deviceId: deviceId,
    timestamp: new Date().toISOString(),
    temperature: parseFloat(d.temperature) || 0,
    temperatureAdc: d.temperatureAdc,
    no2: parseInt(d.no2) || 0,
    ethanol: parseInt(d.ethanol) || 0,
    voc: parseInt(d.voc) || 0,
    co: parseInt(d.co) || 0,
    airQuality: d.airQuality,
    warmup: d.warmup,
    ledText: d.ledText,
    rssi: d.rssi,
    snr: d.snr,
    alerts: d.alerts
};
flow.set('api_devices', devices);

// Historique (max 2000 points par device)
let history = flow.get('api_history_' + deviceId) || [];
history.push(devices[deviceId]);
if (history.length > 2000) history = history.slice(-2000);
flow.set('api_history_' + deviceId, history);

// Stats
let stats = flow.get('api_stats') || { totalMessages: 0, totalAlerts: 0 };
stats.totalMessages++;
if (d.alerts && d.alerts !== 'RAS') stats.totalAlerts++;
flow.set('api_stats', stats);

return msg;

const devices = flow.get('api_devices') || {};
msg.payload = Object.values(devices);
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;

const deviceId = msg.req.params.deviceId;
const hours = parseInt(msg.req.query.hours) || 24;
const history = flow.get('api_history_' + deviceId) || [];

const cutoff = Date.now() - (hours * 3600000);
const filtered = history.filter(h => new Date(h.timestamp).getTime() > cutoff);

msg.payload = filtered;
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;

const stats = flow.get('api_stats') || { totalMessages: 0, totalAlerts: 0 };
const devices = flow.get('api_devices') || {};

msg.payload = {
    totalMessages: stats.totalMessages,
    totalAlerts: stats.totalAlerts,
    activeDevices: Object.keys(devices).length,
    devices: Object.keys(devices)
};
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;
